Here is the root cause:
The bug was caused by incorrectly limiting the maximum allocation size based on the `mm.max_order`, which only considers the largest power-of-two that can fit within the region size. This approach fails when the memory region is set up with a non-power-of-two size, leading to incorrect allocation checks that could reject valid allocation requests. The fix involved changing the condition to use the actual memory region size instead.

Here is the patch:

 int
 __intel_memory_region_get_pages_buddy(struct intel_memory_region *mem,
 				      resource_size_t size,
 				      unsigned int flags,
 				      struct list_head *blocks)
 {
 	unsigned int min_order = 0;
 	unsigned long n_pages;

 	GEM_BUG_ON(!IS_ALIGNED(size, mem->mm.chunk_size));
 	GEM_BUG_ON(!list_empty(blocks));

 	if (flags & I915_ALLOC_MIN_PAGE_SIZE) {
 		min_order = ilog2(mem->min_page_size) -
 			    ilog2(mem->mm.chunk_size);
 	}

 	if (flags & I915_ALLOC_CONTIGUOUS) {
 		size = roundup_pow_of_two(size);
 		min_order = ilog2(size) - ilog2(mem->mm.chunk_size);
 	}

-	if (size > BIT(mem->mm.max_order) * mem->mm.chunk_size)
+	if (size > mem->mm.size)
 		return -E2BIG;

 	n_pages = size >> ilog2(mem->mm.chunk_size);

 	mutex_lock(&mem->mm_lock);

 	do {
 		struct i915_buddy_block *block;
 		unsigned int order;

 		order = fls(n_pages) - 1;
 		GEM_BUG_ON(order > mem->mm.max_order);
 		GEM_BUG_ON(order < min_order);

 		do {
 			block = i915_buddy_alloc(&mem->mm, order);
 			if (!IS_ERR(block))
 				break;

 			if (order-- == min_order)
 				goto err_free_blocks;
 		} while (1);

 		n_pages -= BIT(order);

 		block->private = mem;
 		list_add(&block->link, blocks);

 		if (!n_pages)
 			break;
 	} while (1);

 	mem->avail -= size;
 	mutex_unlock(&mem->mm_lock);
 	return 0;

 err_free_blocks:
 	intel_memory_region_free_pages(mem, blocks);
 	mutex_unlock(&mem->mm_lock);
 	return -ENXIO;
 }



